css:
.blueprintsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2620;
    background: linear-gradient(160deg, #f6f1e7 0%, #efe7d6 100%);
    border-radius: 18px;
}

.blueprintsim-container * {
    box-sizing: border-box;
}

.blueprintsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1b2a4a 0%, #243b66 55%, #2f4d80 100%);
    color: #f7f2e6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(27, 42, 74, 0.30);
    border-bottom: 4px solid #c9a14a;
}

.blueprintsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.blueprintsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0d79a;
    background: rgba(201, 161, 74, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.blueprintsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7ddc8;
}

.blueprintsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3a4d72;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.blueprintsim-period-counter #currentDay,
.blueprintsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1b2a4a;
}

.blueprintsim-round-name {
    background: #e3d6b3;
    color: #5a4517;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.blueprintsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a3b1c;
    background: #f4ddcf;
    padding: 4px 12px;
    border-radius: 999px;
}

.blueprintsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.blueprintsim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e6dcc4;
    box-shadow: 0 4px 14px rgba(27, 42, 74, 0.06);
    border-top: 4px solid #c9a14a;
}

.blueprintsim-card-fit { border-top-color: #1d7a5f; }
.blueprintsim-card-win { border-top-color: #2f4d80; }
.blueprintsim-card-account { border-top-color: #8a5cb0; }
.blueprintsim-card-budget { border-top-color: #c9a14a; }

.blueprintsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7f66;
}

.blueprintsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1b2a4a;
}

.blueprintsim-card-fit .blueprintsim-value { color: #1d7a5f; }
.blueprintsim-card-win .blueprintsim-value { color: #2f4d80; }
.blueprintsim-card-account .blueprintsim-value { color: #8a5cb0; }
.blueprintsim-card-budget .blueprintsim-value { color: #a9821f; }

.blueprintsim-sublabel {
    font-size: 0.76rem;
    color: #9a8e74;
    line-height: 1.35;
}

.blueprintsim-fit-low .blueprintsim-value { color: #b3402a; }
.blueprintsim-fit-high .blueprintsim-value { color: #1d7a5f; }

.blueprintsim-budget-over { border-top-color: #b3402a; }
.blueprintsim-budget-over .blueprintsim-value { color: #b3402a; }

.blueprintsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1b2a4a;
    color: #f2ecdc;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 5px solid #c9a14a;
}

.blueprintsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0d79a;
}

.blueprintsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #c9a14a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(27, 42, 74, 0.05);
}

.blueprintsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.blueprintsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1b2a4a;
    margin-bottom: 6px;
}

.blueprintsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4334;
}

.blueprintsim-briefing-text strong { color: #1d7a5f; }
.blueprintsim-briefing-text em { color: #8a3b1c; font-style: italic; }

.blueprintsim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e6dcc4;
    box-shadow: 0 4px 14px rgba(27, 42, 74, 0.06);
}

.blueprintsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1b2a4a;
    border-bottom: 2px solid #ece2cc;
    padding-bottom: 8px;
}

.blueprintsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #34404f;
    margin: 14px 0 6px;
}

.blueprintsim-container select,
.blueprintsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8ccaf;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf7ee;
    color: #2a2620;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.blueprintsim-container select:focus,
.blueprintsim-container input[type="number"]:focus {
    outline: none;
    border-color: #c9a14a;
    box-shadow: 0 0 0 3px rgba(201, 161, 74, 0.20);
}

.blueprintsim-container select option {
    background-color: #fffdf8;
    color: #2a2620;
}

.blueprintsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c9a14a;
}

.blueprintsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #3a4d72;
    margin-top: 4px;
}

.blueprintsim-range-readout span:last-child {
    color: #1d7a5f;
    font-weight: 800;
}

.blueprintsim-hint {
    font-size: 0.8rem;
    color: #9a8e74;
    margin-top: 4px;
    line-height: 1.4;
}

.blueprintsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.blueprintsim-container .btn-primary {
    background: linear-gradient(135deg, #1b2a4a 0%, #2f4d80 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #f7f2e6;
    box-shadow: 0 6px 16px rgba(27, 42, 74, 0.28);
}

.blueprintsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.blueprintsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8ccaf;
    color: #8a7f66;
}

.blueprintsim-coach {
    background: #1b2a4a;
    color: #f2ecdc;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(27, 42, 74, 0.22);
    border-left: 5px solid #c9a14a;
}

.blueprintsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0d79a;
    margin-bottom: 8px;
}

.blueprintsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.blueprintsim-coach-body strong { color: #f0d79a; }
.blueprintsim-coach-body em { color: #f3c0a6; font-style: italic; }

.blueprintsim-history,
.blueprintsim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e6dcc4;
    box-shadow: 0 4px 14px rgba(27, 42, 74, 0.06);
}

.blueprintsim-history h3,
.blueprintsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1b2a4a;
}

.blueprintsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #34404f;
}

.blueprintsim-container table#usfHistoryTable th {
    background: #f1e9d6;
    color: #1b2a4a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d7bd;
}

.blueprintsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ead9;
}

.blueprintsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ec;
}

.blueprintsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .blueprintsim-container {
        padding: 14px;
    }
    .blueprintsim-header h1 {
        font-size: 1.7rem;
    }
    .blueprintsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .blueprintsim-value {
        font-size: 2rem;
    }
    .blueprintsim-clock {
        margin-left: 0;
    }
    .blueprintsim-period-counter {
        font-size: 0.88rem;
    }
    .blueprintsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .blueprintsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

