(function() {
    'use strict';

    class BlueprintAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `From Brief to Blueprint`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (EUR; money figures in €k).
            this.BUDGET_CAP = 900;        // EUR 900,000 fixed RFP budget
            this.MARGIN_FLOOR = 720;      // 20% operating margin floor → price must be ≥ €720k
            this.FULL_FIDELITY = 1050;    // ~EUR 1.05M full wish-list design cost (exceeds cap)
            this.START_FIT = 30;
            this.START_WIN = 55;
            this.START_ACCOUNT = 25;
            this.PARTICIPANTS = 300;

            // Concept truths.
            this.TRUE_ROOT = `culture`;
            this.TRUE_STANCE = `reframe`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fit: this.START_FIT,
                    win: this.START_WIN,
                    account: this.START_ACCOUNT,
                    budgetUsed: 0,
                    overBudget: false,
                    marginBreach: false,
                    fitHistory: [this.START_FIT],
                    winHistory: [this.START_WIN],
                    accountHistory: [this.START_ACCOUNT],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately a middling / partial play, NOT the textbook win.
                state.decisions = {
                    root: `partial`,
                    stance: `partial`,
                    evidence: 55,
                    scope: `thin`,
                    method: `blended`,
                    depth: 320,
                    measureBuild: `reaction`,
                    position: `bury`,
                    price: 880,
                    politics: `sponsor`,
                    conviction: 55,
                    defend: `ignore`,
                    managers: `mandate`,
                    evidencePlan: `mixed`,
                    dilute: 55
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const stance = document.getElementById(`stanceInput`);
                const ev = document.getElementById(`evidenceInput`);
                if (root) decisions.root = root.value;
                if (stance) decisions.stance = stance.value;
                if (ev) decisions.evidence = parseInt(ev.value, 10);
                if (!Number.isFinite(decisions.evidence) || decisions.evidence < 0 || decisions.evidence > 100) {
                    warn(`warn_evidence_range`); return false;
                }
            } else if (round === 2) {
                const sc = document.getElementById(`scopeInput`);
                const me = document.getElementById(`methodInput`);
                const dp = document.getElementById(`depthInput`);
                const mb = document.getElementById(`measureBuildInput`);
                if (sc) decisions.scope = sc.value;
                if (me) decisions.method = me.value;
                if (dp) decisions.depth = parseFloat(dp.value);
                if (mb) decisions.measureBuild = mb.value;
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 600) {
                    warn(`warn_depth_range`); return false;
                }
            } else if (round === 3) {
                const po = document.getElementById(`positionInput`);
                const pr = document.getElementById(`priceInput`);
                const pl = document.getElementById(`politicsInput`);
                const cv = document.getElementById(`convictionInput`);
                if (po) decisions.position = po.value;
                if (pr) decisions.price = parseFloat(pr.value);
                if (pl) decisions.politics = pl.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.price) || decisions.price < 600 || decisions.price > 1000) {
                    warn(`warn_price_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            } else if (round === 4) {
                const df = document.getElementById(`defendInput`);
                const mg = document.getElementById(`managersInput`);
                const ep = document.getElementById(`evidencePlanInput`);
                const dl = document.getElementById(`diluteInput`);
                if (df) decisions.defend = df.value;
                if (mg) decisions.managers = mg.value;
                if (ep) decisions.evidencePlan = ep.value;
                if (dl) decisions.dilute = parseInt(dl.value, 10);
                if (!Number.isFinite(decisions.dilute) || decisions.dilute < 0 || decisions.dilute > 100) {
                    warn(`warn_dilute_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // fitDelta = quality of the needs diagnosis embedded in the work (the product).
            // winDelta = movement in RFP win probability.
            // accountDelta = month-six NPS / durable account value.
            // spend = design cost added this round (€k).
            let fitDelta = 0, winDelta = 0, accountDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Run the needs diagnosis — separate presenting symptom from root gaps (Common Error 1).
                if (d.root === this.TRUE_ROOT) {
                    fitDelta += 9; accountDelta += 5; coachKey = `coach_r1_root_right`;
                } else if (d.root === `partial`) {
                    fitDelta += 3; coachKey = `coach_r1_partial`;
                } else if (d.root === `literal`) {
                    fitDelta -= 10; accountDelta -= 5; winDelta += 5; coachKey = `coach_r1_literal`;
                } else {
                    fitDelta -= 9; accountDelta -= 6; coachKey = `coach_r1_people`;
                }

                // Diagnosis stance. Confirm raises near-term win but caps fit; reframe is the product.
                if (d.stance === this.TRUE_STANCE) {
                    fitDelta += 6; accountDelta += 4; winDelta -= 5; coachKey = (d.root === this.TRUE_ROOT) ? `coach_r1_diag_sharp` : coachKey;
                } else if (d.stance === `partial`) {
                    fitDelta += 2; winDelta += 2;
                } else {
                    fitDelta -= 8; accountDelta -= 5; winDelta += 9; coachKey = `coach_r1_confirm`;
                }

                // Evidence triangulation — how hard you prove the root cause from multi-source data.
                if (d.evidence >= 60) { fitDelta += 4; accountDelta += 1; }
                else if (d.evidence <= 25) { fitDelta -= 5; coachKey = `coach_r1_thinevidence`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.stance === this.TRUE_STANCE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Configure the costed blueprint (Common Errors 3 & 4).
                // Scope under the cap: prioritize beats wish-list (over budget) and beats thin coverage.
                switch (d.scope) {
                    case `priority`: fitDelta += 6; accountDelta += 4; spend += 300; coachKey = `coach_r2_priority`; break;
                    case `all`: fitDelta += 3; accountDelta += 1; spend += 540; coachKey = `coach_r2_all`; break;
                    case `thin`: fitDelta -= 6; accountDelta -= 4; spend += 120; coachKey = `coach_r2_thin`; break;
                }

                // Method-to-competency fit: practice + coaching builds behaviour; lectures teach about it.
                switch (d.method) {
                    case `practice`: fitDelta += 7; accountDelta += 4; coachKey = (d.scope === `priority`) ? `coach_r2_practice` : coachKey; break;
                    case `blended`: fitDelta += 2; break;
                    case `lecture`: fitDelta -= 9; accountDelta -= 4; coachKey = `coach_r2_lecture`; break;
                }

                // Application-project & coaching depth. Real depth changes behaviour; the wish-list
                // (depth so high total design cost breaches the €900k cap) tanks the margin.
                spend += d.depth;
                if (d.depth >= 260) { fitDelta += 4; accountDelta += 3; }
                else if (d.depth <= 120) { fitDelta -= 5; coachKey = `coach_r2_shallow`; }

                // Measurement built into each module — backward design earns its place.
                switch (d.measureBuild) {
                    case `behaviour`: fitDelta += 4; accountDelta += 4; break;
                    case `reaction`: accountDelta -= 2; break;
                    case `none`: fitDelta -= 4; accountDelta -= 5; coachKey = `coach_r2_nomeasure`; break;
                }

                summaryKey = (d.method === `practice` && d.scope === `priority`) ? `sum_r2_good` : (d.method === `lecture` || d.scope === `all` ? `sum_r2_error` : `sum_r2_weak`);
            } else if (round === 3) {
                // Price, position & win the RFP (Common Errors 2 & 5 + politics).
                // Positioning: leading with the outcome RAISES the win prob of a reframe; burying it
                // wastes a correct diagnosis the client never registers.
                switch (d.position) {
                    case `lead`: winDelta += 15; fitDelta += 4; accountDelta += 3; coachKey = `coach_r3_lead`; break;
                    case `bury`: winDelta -= 9; coachKey = `coach_r3_bury`; break;
                    case `lecture`: winDelta -= 12; accountDelta -= 4; coachKey = `coach_r3_lecture`; break;
                }

                // Price vs the fixed budget and the 20% margin floor.
                if (d.price > this.BUDGET_CAP) {
                    ds.overBudget = true; winDelta -= 16; coachKey = `coach_r3_overbudget`;
                } else if (d.price < this.MARGIN_FLOOR) {
                    ds.marginBreach = true; winDelta += 3; accountDelta -= 9; coachKey = `coach_r3_margin`;
                } else {
                    winDelta += 6; accountDelta += 3;
                }

                // Sponsor-vs-COO split — convince both without surrendering the diagnosis.
                switch (d.politics) {
                    case `both`: winDelta += 10; accountDelta += 5; fitDelta += 3; coachKey = (d.position === `lead`) ? `coach_r3_both` : coachKey; break;
                    case `sponsor`: winDelta -= 4; coachKey = `coach_r3_sponsor`; break;
                    case `coo`: winDelta += 8; fitDelta -= 12; accountDelta -= 10; coachKey = `coach_r3_coo`; break;
                }

                // Conviction in the win-raising case nudges win probability.
                winDelta += Math.round((d.conviction - 55) / 10);

                summaryKey = (d.position === `lead` && d.politics === `both` && !ds.overBudget && !ds.marginBreach) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Defend the diagnosis & prove fit (Common Error 5 + capitulation).
                switch (d.defend) {
                    case `honour`: fitDelta += 6; accountDelta += 9; coachKey = `coach_r4_honour`; break;
                    case `capitulate`: fitDelta -= 15; accountDelta -= 13; coachKey = `coach_r4_capitulate`; break;
                    case `ignore`: accountDelta -= 7; winDelta -= 2; coachKey = `coach_r4_ignore`; break;
                }

                // Resistant line manager — reframe as their own problem vs mandate vs make optional.
                switch (d.managers) {
                    case `reframe`: fitDelta += 4; accountDelta += 6; break;
                    case `mandate`: accountDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_mandate` : coachKey; break;
                    case `drop`: fitDelta -= 10; accountDelta -= 7; coachKey = `coach_r4_drop`; break;
                }

                // Month-six evidence plan — outcome metrics vs a satisfaction smile-sheet.
                switch (d.evidencePlan) {
                    case `outcome`: fitDelta += 4; accountDelta += 10; coachKey = (d.defend === `honour`) ? `coach_r4_outcome` : coachKey; break;
                    case `mixed`: accountDelta += 1; break;
                    case `smile`: accountDelta -= 10; coachKey = `coach_r4_smile`; break;
                }

                // Protecting the design from dilution.
                if (d.dilute >= 60) { fitDelta += 4; accountDelta += 3; }
                else if (d.dilute <= 25) { fitDelta -= 7; accountDelta -= 4; }

                summaryKey = (d.defend === `honour` && d.evidencePlan === `outcome` && d.managers === `reframe`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (design cost accrues across rounds 1–2; cap can bind).
            ds.budgetUsed = Math.max(0, Math.round(ds.budgetUsed + spend));
            if (ds.budgetUsed > this.BUDGET_CAP) {
                ds.overBudget = true;
                // Over the fixed cap → negative-margin design erodes fit credibility and the account.
                const over = ds.budgetUsed - this.BUDGET_CAP;
                accountDelta -= Math.min(30, Math.round(over / 12));
                fitDelta -= Math.min(18, Math.round(over / 22));
            }

            // KPIs move on their deltas, clamped 0–100.
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.win = Math.max(0, Math.min(100, ds.win + winDelta));
            ds.account = Math.max(0, Math.min(100, ds.account + accountDelta));

            ds.fitHistory.push(Math.round(ds.fit));
            ds.winHistory.push(Math.round(ds.win));
            ds.accountHistory.push(Math.round(ds.account));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                win: Math.round(ds.win),
                winDelta: Math.round(winDelta),
                account: Math.round(ds.account),
                accountDelta: Math.round(accountDelta),
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                marginBreach: ds.marginBreach,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

