        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fit);
            const win = Math.round(ds.win);
            const account = Math.round(ds.account);

            const wonReframe = fit >= 65 && win >= 55 && account >= 60;
            const wonLiteral = win >= 60 && fit < 50;
            const composite = Math.round(fit * 0.40 + win * 0.25 + account * 0.35);

            let performanceKey = `lost_rfp`;
            if (wonReframe && composite >= 72) performanceKey = `won_real`;
            else if (wonReframe) performanceKey = `reframe_landed`;
            else if (wonLiteral) performanceKey = `won_literal`;
            else if (win >= 55 && fit >= 50) performanceKey = `credible_compromised`;
            else if (win < 50) performanceKey = `outbid_literal`;
            // Stable, language-independent tier handle for the grading/reporting layer (read from domainState).
            ds.performanceTier = performanceKey;
            // Localized label for the debrief overlay (fixes English label leaking on non-EN screens).
            const performance = window.mySimulation.t(`tier_` + performanceKey);

            const insights = [];
            if (wonReframe) insights.push(window.mySimulation.t(`insight_reframe`));
            else if (wonLiteral) insights.push(window.mySimulation.t(`insight_literal`));
            else if (win < 50) insights.push(window.mySimulation.t(`insight_lost`));
            else insights.push(window.mySimulation.t(`insight_compromised`));

            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (ds.marginBreach) insights.push(window.mySimulation.t(`insight_margin`));
            if (account < 45) insights.push(window.mySimulation.t(`insight_account`));
            if (wonReframe && account >= 70) insights.push(window.mySimulation.t(`insight_growth`));

            return {
                fit: fit,
                win: win,
                account: account,
                wonReframe: wonReframe,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.marginBreach) return window.mySimulation.t(`hint_margin`);
            if (ds.fit < 40 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_fit`);
            if (ds.win < 40 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_win`);
            if (ds.account < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_account`);
            if (ds.fit >= 65 && ds.win >= 55 && ds.account >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

